theorem old_profile_iff {W : Type v} {A : Type u} {I : Type z}
    (F : W → (I → A) → Prop) (w : W) (xs : I → A) :
    liftProfile F w (fun i => some (xs i)) ↔ F w xs

theorem derivable_sound {base : Root → Claim → Prop}
    {rule : Finset Claim → Claim → Prop} {A : Finset Root}
    (meaning : Claim → Prop)
    (roots_sound : ∀ r ∈ A, ∀ c, base r c → meaning c)
    (rules_sound : ∀ P c, rule P c → (∀ p ∈ P, meaning p) → meaning c)
    {c : Claim} (h : Derivable base rule A c) : meaning c
